#include <chrono>
#include <format>
#include <string>

std::string clockText(std::chrono::seconds total)
{
    const auto hours{ std::chrono::duration_cast<std::chrono::hours>(total) };
    total -= hours;
    const auto minutes{ std::chrono::duration_cast<std::chrono::minutes>(total) };
    total -= minutes;
    return std::format("{}:{:02}:{:02}", hours.count(), minutes.count(), total.count());
}

unitTests:
using namespace std::chrono_literals;
TEST("mixed") { CHECK_EQ(clockText(3725s), "1:02:05"); }
TEST("under a minute") { CHECK_EQ(clockText(59s), "0:00:59"); CHECK_EQ(clockText(0s), "0:00:00"); }
TEST("other units convert on the way in") { CHECK_EQ(clockText(2h), "2:00:00"); CHECK_EQ(clockText(90min), "1:30:00"); CHECK_EQ(clockText(25h + 1s), "25:00:01"); }

